# Sequences on one store. seq_step <n> <conclusion> <expected writes> <label>
seq_step() {
  run_listed "$1" 1 "$2"
  payload schedule "${REPO}" "${SEQ_PATH}" "${SEQ_NAME}" "$1"
  report
  expect "$4: night $1 $2" "$3"
}
store seq-nightly
SEQ_PATH="${NIGHTLY}" SEQ_NAME='E2E nightly'
