# workflow_dispatch, push or another head repository: no gh call at all.
for ev in "workflow_dispatch ${REPO}" "push ${REPO}" "schedule evil/Kollect"; do
  store "guard-${ev%% *}-${ev#* }"
  S_GUARD="${S}"
  run_listed 162 1 failure
  payload "${ev%% *}" "${ev#* }"
  report
  n_calls="$(calls | wc -l)"
  if [[ "${RC}" -eq 0 && "${n_calls}" -eq 0 && ! -s "${S_GUARD}/rejected" ]]; then
    ok "trigger: event ${ev%% *}, head ${ev#* }: no gh call (exit 0)"
  else
    bad "trigger: event ${ev%% *}, head ${ev#* }: expected no gh call and exit 0, got ${n_calls} call(s) and exit ${RC}"
  fi
done

# Malformed payload fields: a workflow path off the .github/workflows/<file>.y(a)ml shape, or a
# repository that is not owner/repo, stops the script before any gh call, with a non-zero exit.
# expect_nocall <label>
expect_nocall() {
  local n
  n="$(calls | wc -l)"
  if [[ "${RC}" -ne 0 && "${n}" -eq 0 && ! -s "${S}/rejected" ]]; then
    ok "$1: exit ${RC}, no gh call"
  else
    bad "$1: expected a non-zero exit and no gh call, got exit ${RC} and ${n} call(s)"
  fi
}
for bad_path in '.github/workflows/../x.yaml' '.github/workflows/a b.yaml' '.github/workflows/e2e-nightly.yaml@refs/heads/main'; do
  store "bad-path-${#bad_path}"
  run_listed 162 1 failure
  payload schedule "${REPO}" "${bad_path}"
  report
  expect_nocall "payload: workflow path '${bad_path}'"
done
store bad-repository
run_listed 162 1 failure
payload schedule 'Platform Relay/Kollect'
report GITHUB_REPOSITORY='Platform Relay/Kollect'
expect_nocall "payload: repository 'Platform Relay/Kollect'"

# A workflow name with a new line and a command substitution: one quoted title argument, on one
# line, and nothing runs.
store hostile-name
run_listed 162 1 failure
payload schedule "${REPO}" "${NIGHTLY}" $'E2E nightly\n$(touch pwned)`touch pwned2`'
report
expect "payload: hostile workflow name" "create"
title="$(jq -r 'sort_by(.number) | last | .title // ""' "${S}/issues.json")"
if [[ "${title}" == 'CI failure: E2E nightly$(touch pwned)`touch pwned2`' ]] &&
  [[ -z "$(find "${WORK}" -name 'pwned*' -print -quit)" ]]; then
  ok "payload: hostile workflow name kept verbatim on one title line, nothing ran"
else
  bad "payload: expected the title 'CI failure: E2E nightly\$(touch pwned)\`touch pwned2\`' on one line and no pwned file, got '${title}'"
fi

# Attempt 2 of a failing run reports; the fake refuses a run read without --attempt 2.
store attempt-2
run_listed 162 2 failure
payload
report
expect "attempt: failing 162.2" "create"
expect_marker "attempt: failing 162.2" "${LAST_ISSUE}" "$(marker "${NIGHTLY}" 990162 162.2 failure)"
n_reads="$(calls | grep -cE '^(jobs|log)$')" || true
if [[ "${n_reads}" -ge 2 ]]; then
  ok "attempt: ${n_reads} run reads, each with --attempt 2 (the fake refuses others)"
else
  bad "attempt: expected the jobs and log reads with --attempt 2, got ${n_reads} run read(s)"
fi

# Every create and comment passes its body through --body-file; the close is bodyless.
store body-file
run_listed 162 1 success
issue 10 OPEN "${NIGHTLY}" 161.1 failure
payload
report
bodyless=1
for f in "${S}"/calls/*; do
  [[ -f "${f}" ]] || continue
  case "$(kind "${f}")" in
  create | comment*) grep -qx -- '--body-file' "${f}" || bodyless=0 ;;
  close*) [[ "$(wc -l <"${f}")" -eq 3 ]] || bodyless=0 ;;
  esac
done
if [[ "${bodyless}" -eq 1 && "$(writes)" == "comment 10, close 10" ]]; then
  ok "writes: comment through --body-file, bodyless close"
else
  bad "writes: expected a --body-file comment and a bare 'issue close 10', got '$(writes)'"
fi

# A non-numeric run id, run number, attempt or issue number: exit non-zero, no write, and no gh
# call after the one that returned it (the value never reaches a later call).
# expect_stop <label> <kind of the last call>
expect_stop() {
  local last
  last="$(calls | tail -n 1)"
  if [[ "${RC}" -ne 0 && "$(writes)" == none && "${last}" == "$2" && ! -s "${S}/rejected" ]]; then
    ok "$1: exit ${RC}, no call after ${last}"
  else
    bad "$1: expected a non-zero exit, no write and '$2' as the last call, got exit ${RC}, writes '$(writes)', last call '${last}'"
  fi
}
i=0
for bad_run in '"990162x" 162 1' '990162 "162x" 1' '990162 162 "1;2"'; do
  i=$((i + 1))
  store "non-numeric-run-${i}"
  read -r id num att <<<"${bad_run}"
  jq -n --argjson id "${id}" --argjson n "${num}" --argjson a "${att}" \
    '[{attempt: $a, conclusion: "failure", databaseId: $id, number: $n}]' >"${S}/runs.json"
  payload
  report
  expect_stop "numeric: run list entry ${bad_run}" run-list
done
store non-numeric-issue
run_listed 162 1 success
issue 10 OPEN "${NIGHTLY}" 161.1 failure
jq 'map(.number = "10 ")' "${S}/issues.json" >"${S}/issues.new"
mv "${S}/issues.new" "${S}/issues.json"
payload
report
expect_stop "numeric: issue number '10 '" issue-list

# gh exiting 0 with empty or malformed output at each read (B1): the output must be exactly one
# JSON document of the expected shape (an array; for jobs and comments an object holding that
# array). Otherwise exit non-zero, say so on stderr, no write, and no call after that read. An
# empty issue list read as "no issue" would open a duplicate; empty comments read as "no comment"
# would fall back to the body key and comment again; an empty job list of a cancelled run would
# read as "no job started" and drop the report.
for k in run-list jobs issue-list issue-view; do
  case "${k}" in
  issue-view) wrong='{"comments": "x"}' two='{"comments": []} {"comments": []}' ;;
  jobs) wrong='{"jobs": "x"}' two='{"jobs": []} {"jobs": []}' ;;
  *) wrong='{"total": 0}' two='[] []' ;;
  esac
  for shape in empty garbage two wrong; do
    store "gh-output-${k}-${shape}"
    if [[ "${k}" == jobs ]]; then
      run_listed 162 1 cancelled
    else
      run_listed 162 1 failure
    fi
    if [[ "${k}" == issue-view ]]; then
      issue 10 OPEN "${NIGHTLY}" 161.1 failure
    fi
    if ((!SKIP)); then
      case "${shape}" in
      empty) : >"${S}/raw-${k}" ;;
      garbage) echo 'not json' >"${S}/raw-${k}" ;;
      two) echo "${two}" >"${S}/raw-${k}" ;;
      wrong) echo "${wrong}" >"${S}/raw-${k}" ;;
      esac
    fi
    payload
    report
    expect_stop "gh output: ${k} ${shape}" "${k}"
    if ((!SKIP)) && ! grep -qF 'did not return one JSON document of the expected shape' "${ERR}"; then
      bad "gh output: ${k} ${shape}: expected 'did not return one JSON document of the expected shape' on stderr, got: $(head -c 300 "${ERR}" | tr '\n' ' ')"
    fi
  done
done

# gh exiting non-zero at each call in turn: exit non-zero, the gh error on stderr, and the
# failing call is the last call made.
for k in run-list jobs issue-list issue-view create comment close; do
  store "gh-error-${k}"
  case "${k}" in
  run-list | jobs | issue-list | create) run_listed 162 1 failure ;;
  issue-view | comment)
    run_listed 162 1 failure
    issue 10 OPEN "${NIGHTLY}" 161.1 failure
    ;;
  close)
    run_listed 162 1 success
    issue 10 OPEN "${NIGHTLY}" 161.1 failure
    ;;
  esac
  echo "${k}" >"${S}/fail"
  payload
  report
  last="$(calls | tail -n 1)"
  if [[ "${RC}" -ne 0 && "${last%% *}" == "${k}" && ! -s "${S}/rejected" ]] &&
    grep -qF "injected fake gh error (${k})" "${ERR}"; then
    ok "gh error at ${k}: exit ${RC}, error on stderr, no call after it"
  else
    bad "gh error at ${k}: expected a non-zero exit, the injected error on stderr and '${k}' as the last call, got exit ${RC}, last call '${last}'"
  fi
done

# Recovery comment written, close fails, the reporter runs again: one close, no second comment.
store close-retry
run_listed 162 1 success
issue 10 OPEN "${NIGHTLY}" 161.1 failure
echo close >"${S}/fail"
touch "${S}/fail-once"
payload
report
expect "close retry: first run (close fails)" "comment 10, close 10" nonzero
report
expect "close retry: second run" "close 10"
if [[ "$(jq '[.[] | select(.number == 10)][0] | [.state, (.comments | length)] | join(" ")' -r "${S}/issues.json")" == "CLOSED 1" ]]; then
  ok "close retry: issue closed with one recovery comment"
else
  bad "close retry: expected issue 10 CLOSED with 1 comment, got $(jq -c '[.[] | select(.number == 10)][0] | [.state, (.comments | length)]' "${S}/issues.json")"
fi

# Log fetch exits non-zero, and separately exits 0 with empty output: the issue is still opened
# with the job names and "logs unavailable", and the script exits non-zero.
for mode in fail empty; do
  store "log-${mode}"
  run_listed 162 1 failure
  rc_env="FAKE_GH_LOG_RC=0"
  if [[ "${mode}" == fail ]]; then
    rm -f "${S}/log.txt"
    rc_env="FAKE_GH_LOG_RC=1"
  else
    : >"${S}/log.txt"
  fi
  payload
  report "${rc_env}"
  expect "log fetch ${mode}" "create" nonzero
  created="$(jq -r "${LAST_ISSUE} // \"\"" "${S}/issues.json")"
  if grep -qF 'logs unavailable' <<<"${created}" && grep -qF 'e2e-multitenant' <<<"${created}" &&
    grep -qF 'e2e-finalizer-cleanup' <<<"${created}"; then
    ok "log fetch ${mode}: body lists both failed jobs and says logs unavailable"
  else
    bad "log fetch ${mode}: expected the body to list e2e-multitenant and e2e-finalizer-cleanup and say 'logs unavailable'"
  fi
done

# =============================================================================================
# Workflow wiring (CFR-1, CFR-6, CFR-7): .github/workflows/ci-failure-report.yaml. Each check
# reports what it found, also when the file is absent, so one run names every missing piece.
# =============================================================================================
command -v yq >/dev/null 2>&1 || {
  echo "FAIL: yq not found; install yq to run the workflow wiring checks" >&2
  exit 1
}
select_case wiring
WF="${ROOT}/.github/workflows/ci-failure-report.yaml"
WF_REL=".github/workflows/ci-failure-report.yaml"

# wq <yq expression>: the expression on the workflow as compact JSON, or <missing file> /
# <parse error>, so a check on an absent file still names what it looked for.
wq() {
  if ((SKIP)); then
    echo "<skipped>"
    return 0
  fi
  [[ -f "${WF}" ]] || {
    echo "<missing file>"
    return 0
  }
  yq eval -o=json -I=0 "$1" "${WF}" 2>/dev/null || echo "<parse error>"
}

# Reported workflows: exactly E2E nightly, Go patch lag and Test shuffle (TDS-2, openspec change
# test-depth-signals), each the name: of exactly one workflow file (workflow_run matches by name,
# so a rename silently stops the trigger).
listed="$(wq '."on".workflow_run.workflows')"
if [[ "${listed}" == '["E2E nightly","Go patch lag","Test shuffle"]' ]]; then
  ok "wiring: workflow_run lists exactly E2E nightly, Go patch lag and Test shuffle"
else
  bad "wiring: ${WF_REL} on.workflow_run.workflows must be exactly [\"E2E nightly\",\"Go patch lag\",\"Test shuffle\"], found ${listed}"
fi
listed_names=()
if [[ -f "${WF}" ]]; then
  mapfile -t listed_names < <(yq eval '."on".workflow_run.workflows[]' "${WF}" 2>/dev/null || true)
fi
if ((SKIP)); then
  listed_names=() # filtered out: no yq call per workflow file and listed name
fi
[[ "${#listed_names[@]}" -gt 0 ]] ||
  bad "wiring: ${WF_REL} lists no workflow under on.workflow_run.workflows to match against the workflow files' name:"
for name in "${listed_names[@]}"; do
  n=0
  for f in "${ROOT}"/.github/workflows/*.yaml "${ROOT}"/.github/workflows/*.yml; do
    [[ -f "${f}" ]] || continue
    if [[ "$(yq eval '.name // ""' "${f}" 2>/dev/null)" == "${name}" ]]; then
      n=$((n + 1))
    fi
  done
  if [[ "${n}" -eq 1 ]]; then
    ok "wiring: listed workflow '${name}' is the name: of exactly one workflow file"
  else
    bad "wiring: listed workflow '${name}' matches the name: of ${n} workflow files, expected exactly 1 (workflow_run matches by name and stops firing silently on a rename)"
  fi
done

# workflow_run is the only trigger: the zizmor dangerous-triggers exception covers the whole file,
# so a second trigger (pull_request_target, workflow_dispatch) would be silenced with it.
on_keys="$(wq '."on" | keys')"
if [[ "${on_keys}" == '["workflow_run"]' ]]; then
  ok "wiring: workflow_run is the only trigger"
else
  bad "wiring: ${WF_REL} on: must hold only workflow_run (the zizmor exception covers the whole file), found ${on_keys}"
fi

types="$(wq '."on".workflow_run.types')"
if [[ "${types}" == '["completed"]' ]]; then
  ok "wiring: workflow_run types is [completed] only"
else
  bad "wiring: ${WF_REL} on.workflow_run.types must be exactly [completed], found ${types}"
fi

# One job; its if: is exactly the schedule and same-repository guard (CFR-6), no weaker form.
jobs_n="$(wq '.jobs | length')"
if [[ "${jobs_n}" == 1 ]]; then
  ok "wiring: one job"
else
  bad "wiring: ${WF_REL} must have exactly one job, found ${jobs_n}"
fi
want_if="github.event.workflow_run.event == 'schedule' && github.event.workflow_run.head_repository.full_name == github.repository"
got_if="$(wq '.jobs | to_entries | .[0].value.if // "<no if>"')"
got_if="$(jq -r '.' <<<"${got_if}" 2>/dev/null || echo "${got_if}")"
if [[ "$(tr -s '[:space:]' ' ' <<<"${got_if}" | sed 's/^ //; s/ $//')" == "${want_if}" ]]; then
  ok "wiring: the job's if: requires a schedule event of this repository"
else
  bad "wiring: ${WF_REL} job if: must be exactly \"${want_if}\", found ${got_if}"
fi

# Job level, not workflow level (B3): a workflow-level group also queues the runs whose job the
# if: skips, so a dispatched run's report could replace a pending scheduled one.
conc="$(wq '[.concurrency, (.jobs | to_entries | .[0].value.concurrency.group), (.jobs | to_entries | .[0].value.concurrency."cancel-in-progress")]')"
# shellcheck disable=SC2016 # the GitHub expression is the expected text, not a shell expansion
want_conc='[null,"ci-failure-report-${{ github.event.workflow_run.workflow_id }}",false]'
if [[ "${conc}" == "${want_conc}" ]]; then
  ok "wiring: job concurrency group ci-failure-report-<workflow_id>, cancel-in-progress false, none at workflow level"
else
  bad "wiring: ${WF_REL} concurrency must be ${want_conc} as [workflow concurrency, job group, job cancel-in-progress], found ${conc}"
fi

wperm="$(wq '.permissions')"
if [[ "${wperm}" == '{"contents":"read"}' ]]; then
  ok "wiring: workflow permissions contents: read"
else
  bad "wiring: ${WF_REL} workflow permissions must be exactly {contents: read}, found ${wperm}"
fi
jperm="$(wq '.jobs | to_entries | .[0].value.permissions | to_entries | map(.key + "=" + .value) | sort')"
if [[ "${jperm}" == '["actions=read","contents=read","issues=write"]' ]]; then
  ok "wiring: job permissions exactly contents: read, actions: read, issues: write"
else
  bad "wiring: ${WF_REL} job permissions must be exactly contents: read, actions: read, issues: write, found ${jperm}"
fi

# No checkout of the triggering run: every actions/checkout has persist-credentials: false and
# no ref: or repository:.
checkouts="$(wq '[.jobs[].steps[] | select((.uses // "") | test("^actions/checkout@"))] | length')"
bad_co="$(wq '[.jobs[].steps[] | select((.uses // "") | test("^actions/checkout@")) | select(.with."persist-credentials" != false or (.with | has("ref")) or (.with | has("repository")))] | length')"
if [[ "${checkouts}" =~ ^[1-9][0-9]*$ && "${bad_co}" == 0 ]]; then
  ok "wiring: ${checkouts} checkout(s), each persist-credentials: false with no ref: or repository:"
else
  bad "wiring: ${WF_REL} needs actions/checkout of the default branch only (persist-credentials: false, no ref:, no repository:), found ${checkouts} checkout(s), ${bad_co} offending"
fi

# Steps: the label create (fixed colour and description) comes before the reporter step; no run:
# interpolates the event; the token reaches gh through env:.
label_idx=""
report_idx=""
label_n=0
report_n=0
inject=""
if [[ -f "${WF}" ]] && ! ((SKIP)); then
  nsteps="$(yq eval '.jobs | to_entries | .[0].value.steps | length' "${WF}" 2>/dev/null || echo 0)"
  for ((i = 0; i < nsteps; i++)); do
    raw_body="$(yq eval ".jobs | to_entries | .[0].value.steps[${i}].run // \"\"" "${WF}")"
    run_body="$(grep -v '^[[:space:]]*#' <<<"${raw_body}" || true)"
    if grep -qE '(^|[[:space:]])gh label create ci-failure --force([[:space:]]|$)' <<<"${run_body}"; then
      label_n=$((label_n + 1))
      if grep -qE -- "--color [0-9A-Fa-f]{6}([[:space:]]|$)" <<<"${run_body}" &&
        grep -qE -- "--description '[^'\$]+'" <<<"${run_body}"; then
        label_idx="${i}"
      fi
    fi
    # The reporter takes no arguments (G3 interface): the step's code is exactly the one call.
    if grep -qF 'ci-failure-report.sh' <<<"${run_body}"; then
      report_n=$((report_n + 1))
      if [[ "$(tr -s '[:space:]' ' ' <<<"${run_body}" | sed 's/^ //; s/ $//')" == 'bash hack/ci/ci-failure-report.sh' ]]; then
        report_idx="${i}"
      fi
    fi
    # Any expression in a run: body, comment lines included: GitHub expands ${{ }} before the
    # shell parses the script, so a comment is no shelter. Values reach scripts through env:.
    if grep -qF '${{' <<<"${raw_body}"; then
      inject="${inject} ${i}"
    fi
  done
fi
if [[ "${label_n}" -eq 1 && -n "${label_idx}" ]]; then
  ok "wiring: one step runs gh label create ci-failure --force with a fixed --color and --description"
else
  bad "wiring: ${WF_REL} needs exactly one step running 'gh label create ci-failure --force --color <hex6> --description '<text>'' (fixed values), found ${label_n} label step(s), fixed colour and description: ${label_idx:-none}"
fi
if [[ "${report_n}" -eq 1 && -n "${report_idx}" ]]; then
  ok "wiring: one step runs exactly 'bash hack/ci/ci-failure-report.sh' (no arguments)"
else
  bad "wiring: ${WF_REL} needs exactly one step whose run: is exactly 'bash hack/ci/ci-failure-report.sh' (the reporter takes no arguments), found ${report_n} step(s) naming it, exact: ${report_idx:-none}"
fi
if [[ -n "${label_idx}" && -n "${report_idx}" && "${label_idx}" -lt "${report_idx}" ]]; then
  ok "wiring: the label step (${label_idx}) precedes the report step (${report_idx})"
else
  bad "wiring: ${WF_REL} the label-create step must precede the report step, found label step ${label_idx:-none}, report step ${report_idx:-none}"
fi
if [[ -f "${WF}" && -z "${inject}" ]]; then
  ok "wiring: no run: body holds a \${{ }} expression, comments included"
else
  bad "wiring: ${WF_REL} run: bodies must hold no \${{ }} expression, comment lines included (GitHub expands it before the shell runs; values reach scripts through env:), found in step(s) ${inject:-<missing file>}"
fi
# Exactly three steps: the checkout, the label step, the reporter step. Any other step could use
# event data (through env: or with:) under this privileged trigger without another check seeing it.
steps_shape="$(wq '[.jobs | to_entries | .[0].value.steps[] | ((.uses // "") | sub("@.*$"; "")) + "|" + ((.run // "") | sub("\\s+$"; ""))]')"
first_uses="$(wq '.jobs | to_entries | .[0].value.steps[0].uses // ""' | jq -r '.' 2>/dev/null || true)"
if [[ "$(wq '.jobs | to_entries | .[0].value.steps | length')" == 3 && "${first_uses}" == actions/checkout@* &&
  "${label_idx}" == 1 && "${report_idx}" == 2 ]]; then
  ok "wiring: exactly three steps: checkout, label, report"
else
  bad "wiring: ${WF_REL} job steps must be exactly [actions/checkout, the label step, the report step], found ${steps_shape}"
fi
# shellcheck disable=SC2016 # the GitHub expression is the expected text
want_tok='${{ github.token }}'
tok="$(wq "[(.jobs | to_entries | .[0].value.steps[${label_idx:-0}].env.GH_TOKEN), (.jobs | to_entries | .[0].value.steps[${report_idx:-0}].env.GH_TOKEN)]")"
if [[ "${tok}" == "[\"${want_tok}\",\"${want_tok}\"]" ]]; then
  ok "wiring: the label and report steps get GH_TOKEN through env:"
else
  bad "wiring: ${WF_REL} the label and report steps must set env GH_TOKEN: ${want_tok}, found ${tok}"
fi

# The comment directly above the workflows: list names the race gap and SINK-BREAKER-RACE-01.
wf_comment=""
if [[ -f "${WF}" ]]; then
  wf_comment="$(awk '
    /^[[:space:]]*#/ { block = block $0 "\n"; next }
    /^[[:space:]]+workflows:/ { printf "%s", block; exit }
    { block = "" }
  ' "${WF}")"
fi
if grep -qw 'race' <<<"${wf_comment}" && grep -qF 'SINK-BREAKER-RACE-01' <<<"${wf_comment}"; then
  ok "wiring: the comment above the workflow list names the race gap and SINK-BREAKER-RACE-01"
else
  bad "wiring: ${WF_REL} needs a comment directly above on.workflow_run.workflows naming the race gap and SINK-BREAKER-RACE-01, found '${wf_comment:-<none>}'"
fi

# The dangerous-triggers exception in .github/zizmor.yml covers this workflow only.
zig="$(yq eval -o=json -I=0 '.rules."dangerous-triggers".ignore' "${ROOT}/.github/zizmor.yml" 2>/dev/null || echo "<parse error>")"
if [[ "${zig}" == '["ci-failure-report.yaml"]' ]]; then
  ok "wiring: zizmor dangerous-triggers ignores ci-failure-report.yaml only"
else
  bad "wiring: .github/zizmor.yml rules.dangerous-triggers.ignore must be exactly [ci-failure-report.yaml], found ${zig}"
fi

# =============================================================================================
# Self-wiring (CFR-7): ci.yaml runs this test bare and with --self-test, each on an uncommented
# line. No other gate names this test (CFC-6's fixed list does not), and CWS-6 only pins the modes
# of a guard CI already runs, so deleting both steps would drop it from CI silently.
# =============================================================================================
select_case self-wiring
CI_YAML="${ROOT}/.github/workflows/ci.yaml"
for form in "bash hack/test/ci_failure_report_test.sh" "bash hack/test/ci_failure_report_test.sh --self-test"; do
  n=0
  if [[ -f "${CI_YAML}" ]]; then
    n="$(grep -v '^[[:space:]]*#' "${CI_YAML}" |
      sed -E 's/^[[:space:]]*//; s/[[:space:]]*$//; s/^-[[:space:]]*//; s/^run:[[:space:]]*//' |
      grep -cFx -- "${form}" || true)"
  fi
  if [[ "${n}" -ge 1 ]]; then
    ok "self-wiring: .github/workflows/ci.yaml runs '${form}' on an uncommented line"
  else
    bad "self-wiring: .github/workflows/ci.yaml must run '${form}' on an uncommented line (a step's run:), found ${n}$([[ -f "${CI_YAML}" ]] || echo ' (file missing)')"
  fi
done

if [[ -n "${ONLY}" && "${SELECTED}" -eq 0 ]]; then
  SKIP=0
  bad "CFR_SELFTEST_ONLY='${ONLY}' names no case; nothing was checked"
fi
if [[ "${FAILURES}" -gt 0 ]]; then
  echo "ci_failure_report_test: ${FAILURES} check(s) failed" >&2
  exit 1
fi
echo "All ci-failure-report checks passed."
